source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find the non-background, full-width divider line.
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            lines.append(('row', r, row[0]))
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != background:
            lines.append(('col', c, col[0]))
    if not lines:
        return [row[:] for row in grid]
    # A task divider is the full line of a color distinct from the background.
    axis, divider, divider_color = lines[0]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (background, divider_color)]
    if not points:
        return [row[:] for row in grid]
    obj_color = Counter(grid[r][c] for r, c in points).most_common(1)[0][0]
    points = [(r, c) for r, c in points if grid[r][c] == obj_color]

    out = [[background for _ in range(w)] for _ in range(h)]
    # Keep the divider fixed. Move the object to the adjacent side of it.
    if axis == 'row':
        for c in range(w):
            out[divider][c] = divider_color
        lo, hi = min(r for r, c in points), max(r for r, c in points)
        if hi < divider:
            shift = divider - 1 - hi
            stripe = lo + shift - 1
        else:
            shift = divider + 1 - lo
            stripe = hi + shift + 1
        for r, c in points:
            out[r + shift][c] = obj_color
        if 0 <= stripe < h and stripe != divider:
            for c in range(w):
                out[stripe][c] = 8
    else:
        for r in range(h):
            out[r][divider] = divider_color
        lo, hi = min(c for r, c in points), max(c for r, c in points)
        if hi < divider:
            shift = divider - 1 - hi
            stripe = lo + shift - 1
        else:
            shift = divider + 1 - lo
            stripe = hi + shift + 1
        for r, c in points:
            out[r][c + shift] = obj_color
        if 0 <= stripe < w and stripe != divider:
            for r in range(h):
                out[r][stripe] = 8
    return out
